        single[7] + "]";
}

public void transform(Point2D point)
{
    float x = (float)point.getX();
    float y = (float)point.getY();
    float a = single[0];
    float b = single[1];
    float c = single[3];
    float d = single[4];
    float e = single[6];
    float f = single[7];
    point.setLocation(x * a + y * c + e, x * b + y * d + f);
}

public Vector transform(Vector vector)
{
    float a = single[0];
    float b = single[1];
    float c = single[3];
    float d = single[4];
    float e = single[6];
    float f = single[7];
    float x = vector.getX();
    float y = vector.getY();
    return new Vector(x * a + y * c + e, x * b + y * d + f);
}

public Point2D.Float transformPoint(float x, float y)
{
    float a = single[0];
    float b = single[1];
    float c = single[3];
    float d = single[4];
    float e = single[6];
    float f = single[7];
    return new Point2D.Float(x * a + y * c + e, x * b + y * d + f);
}

