public AccessPermission()
{
    bytes = DEFAULT_PERMISSIONS;
}

public AccessPermission(byte[] b)
{
    bytes = 0;
    bytes |= b[0] & 0xFF;
    bytes <<= 8;
    bytes |= b[1] & 0xFF;
    bytes <<= 8;
    bytes |= b[2] & 0xFF;
    bytes <<= 8;
    bytes |= b[3] & 0xFF;
}

public AccessPermission( int permissions )
{
    bytes = permissions;
}

